            new_t = -kp_use * e_arr[i] - kd_use * w_arr[i] - ki_use * iprop_arr[i];
            if (fabs(new_t) > fabs(old_t) && (new_t * old_t > 0.0) &&
                (old_t > ra_config.torque_limit_nm ||
                 old_t < -ra_config.torque_limit_nm)) {
                iuse_arr[i] = iprev_arr[i];
            }
        }
    }
}
for (i = 0; i < 3; i++) {
    t_unlim[i] = -kp_use * e_arr[i] - kd_use * w_arr[i] - ki_use * iuse_arr[i];
}
sat_mask = 0U;
for (i = 0; i < 3; i++) {
    double limited = 0.0;
    (void)adcs_limit_scalar(t_unlim[i], &lim, &limited);
    t_lim[i] = limited;
    if (t_unlim[i] > ra_config.torque_limit_nm ||
        t_unlim[i] < -ra_config.torque_limit_nm) {
        sat_mask |= (uint32_t)(1U << i);
    }
}

if (next_mode == RA_FINE || next_mode == RA_HOLD) {
    ra_state.integral_error_rad_s = (adcs_vec3_t){iuse_arr[0], iuse_arr[1], iuse_arr[2]};
} else {
    ra_state.integral_error_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
}

torque = (adcs_vec3_t){t_lim[0], t_lim[1], t_lim[2]};

ra_output.mode = next_mode;
ra_output.error_angle_rad = angle;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.torque_nm = torque;
ra_output.bad_samples = 0U;
ra_output.saturation_mask = sat_mask;
return;

candidates.misra:
int en, va;
adcs_quat_t qc, qt, qe;
adcs_vec3_t e_vec, w;
double angle, rate_mag;
adcs_vec3_t torque;
uint32_t sat_mask = 0U;
adcs_actuator_limit_t lim;
ra_mode_t next_mode;
int rejected = 0;
double kp_use, kd_use, ki_use;
size_t i;
double e_arr[3], w_arr[3], t_unlim[3], t_lim[3], iprev_arr[3], iprop_arr[3], iuse_arr[3];

en = ra_input.enable;
va = ra_input.valid;

/* 1. configuration validation */
if (!(ra_config.hold_enter_rad >= 0.0 &&
      ra_config.hold_enter_rad < ra_config.hold_exit_rad &&
      ra_config.hold_exit_rad <= ra_config.fine_enter_rad &&
      ra_config.fine_enter_rad < ra_config.fine_exit_rad &&
      ra_config.fine_exit_rad <= ADCS_PI &&
      ra_config.hold_rate_rad_s >= 0.0 &&
      ra_config.hold_rate_rad_s < ra_config.hold_rate_exit_rad_s &&
      ra_config.hold_rate_exit_rad_s <= ra_config.rate_enter_rad_s &&
      ra_config.rate_enter_rad_s < ra_config.rate_exit_rad_s &&
      isfinite(ra_config.hold_enter_rad) &&
      isfinite(ra_config.hold_exit_rad) &&
      isfinite(ra_config.fine_enter_rad) &&
      isfinite(ra_config.fine_exit_rad) &&
      isfinite(ra_config.rate_enter_rad_s) &&
      isfinite(ra_config.rate_exit_rad_s) &&
      isfinite(ra_config.hold_rate_rad_s) &&
      isfinite(ra_config.hold_rate_exit_rad_s) &&
      isfinite(ra_config.kp) && ra_config.kp >= 0.0 &&
      isfinite(ra_config.kd) && ra_config.kd >= 0.0 &&
      isfinite(ra_config.ki) && ra_config.ki >= 0.0 &&
      isfinite(ra_config.dt_s) && ra_config.dt_s > 0.0 &&
      isfinite(ra_config.integral_limit_rad_s) && ra_config.integral_limit_rad_s > 0.0 &&
      isfinite(ra_config.torque_limit_nm) && ra_config.torque_limit_nm > 0.0 &&
      ra_config.rate_samples >= 1U && ra_config.rate_samples <= 20U &&
      ra_config.fine_samples >= 1U && ra_config.fine_samples <= 20U &&
      ra_config.hold_samples >= 1U && ra_config.hold_samples <= 20U &&
      ra_config.max_bad_samples >= 1U && ra_config.max_bad_samples <= 20U)) {
    rejected = 1;
}

if (!rejected) {
    if ((en != 0 && en != 1) || (va != 0 && va != 1)) {
        rejected = 1;
    } else if (va == 0) {
        rejected = 1;
    } else if (ra_input.current_q_bi == NULL || ra_input.target_q_bi == NULL ||
               ra_input.body_rate_rad_s == NULL) {
        rejected = 1;
    } else if (!adcs_is_finite_vec3(ra_input.body_rate_rad_s)) {
        rejected = 1;
    } else if (adcs_quat_normalize(ra_input.current_q_bi, &qc) != ADCS_OK) {
        rejected = 1;
    } else if (adcs_quat_normalize(ra_input.target_q_bi, &qt) != ADCS_OK) {
        rejected = 1;
    } else {
        (void)0; /* input accepted: all rejection checks passed */
    }
}

/* reject / FAULT latched path */
if (rejected) {
    ra_state.transition_samples = 0U;
    ra_state.integral_error_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    if (ra_state.bad_samples < 0xFFFFFFFFU) {
        ra_state.bad_samples += 1U;
    }
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    }
    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = 0U;
    return;
}

/* accepted cycle resets bad samples */
ra_state.bad_samples = 0U;

/* disable -> OFF, clear all evidence and integral, zero torque */
if (en == 0) {
    ra_state.mode = RA_OFF;
    ra_state.transition_samples = 0U;
    ra_state.integral_error_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    ra_output.mode = RA_OFF;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    ra_output.bad_samples = 0U;
    ra_output.saturation_mask = 0U;
    return;
}

/* error quaternion q_err = target * conj(current) */
{
    adcs_quat_t qcc = adcs_quat_conjugate(&qc);
    qe = adcs_quat_multiply(&qt, &qcc);
}
if (qe.w < 0.0) {
    qe.w = -qe.w;
    qe.x = -qe.x;
    qe.y = -qe.y;
    qe.z = -qe.z;
}
{
    double s = sqrt(qe.x * qe.x + qe.y * qe.y + qe.z * qe.z);
    if (s < 1.0e-12) {
        angle = 0.0;
        e_vec.x = 0.0;
        e_vec.y = 0.0;
        e_vec.z = 0.0;
    } else {
        angle = 2.0 * atan2(s, qe.w);
        e_vec.x = (qe.x / s) * angle;
        e_vec.y = (qe.y / s) * angle;
        e_vec.z = (qe.z / s) * angle;
    }
}
w = *ra_input.body_rate_rad_s;
rate_mag = adcs_vec3_norm(&w);

e_arr[0] = e_vec.x;
e_arr[1] = e_vec.y;
e_arr[2] = e_vec.z;
w_arr[0] = w.x;
w_arr[1] = w.y;
w_arr[2] = w.z;

/* mode transition: uses the mode entered this cycle for the control law */
next_mode = ra_state.mode;
if (ra_state.mode == RA_OFF || ra_state.mode == RA_FAULT) {
    if (rate_mag > ra_config.rate_enter_rad_s) {
        next_mode = RA_RATE_DAMP;
    } else {
        next_mode = RA_COARSE;
    }
    ra_state.transition_samples = 0U;
} else if (ra_state.mode == RA_RATE_DAMP) {
    if (rate_mag > ra_config.rate_exit_rad_s) {
        ra_state.transition_samples = 0U;
    } else if (rate_mag <= ra_config.rate_enter_rad_s) {
        ra_state.transition_samples += 1U;
        if (ra_state.transition_samples >= ra_config.rate_samples) {
            ra_state.transition_samples = 0U;
            next_mode = RA_COARSE;
        }
    } else {
        ra_state.transition_samples = 0U;
    }
} else if (ra_state.mode == RA_COARSE) {
    if (angle <= ra_config.fine_enter_rad && rate_mag <= ra_config.rate_enter_rad_s) {
        ra_state.transition_samples += 1U;
        if (ra_state.transition_samples >= ra_config.fine_samples) {
            ra_state.transition_samples = 0U;
            next_mode = RA_FINE;
        }
    } else {
        ra_state.transition_samples = 0U;
    }
} else if (ra_state.mode == RA_FINE) {
    if (angle >= ra_config.fine_exit_rad || rate_mag >= ra_config.rate_exit_rad_s) {
        next_mode = RA_COARSE;
        ra_state.transition_samples = 0U;
        ra_state.integral_error_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    } else if (angle <= ra_config.hold_enter_rad && rate_mag <= ra_config.hold_rate_rad_s) {
        ra_state.transition_samples += 1U;
        if (ra_state.transition_samples >= ra_config.hold_samples) {
            ra_state.transition_samples = 0U;
            next_mode = RA_HOLD;
        }
    } else {
        ra_state.transition_samples = 0U;
    }
} else if (ra_state.mode == RA_HOLD) {
    if (angle >= ra_config.hold_exit_rad || rate_mag >= ra_config.hold_rate_exit_rad_s) {
        next_mode = RA_FINE;
        ra_state.transition_samples = 0U;
    }
} else {
    /* no transition */
}
ra_state.mode = next_mode;

/* control law gains by mode */
if (next_mode == RA_RATE_DAMP) {
    kp_use = 0.0;
    kd_use = ra_config.kd;
    ki_use = 0.0;
} else if (next_mode == RA_COARSE) {
    kp_use = ra_config.kp;
    kd_use = ra_config.kd;
    ki_use = 0.0;
} else if (next_mode == RA_FINE || next_mode == RA_HOLD) {
    kp_use = ra_config.kp;
    kd_use = ra_config.kd;
    ki_use = ra_config.ki;
} else {
    /* unconditional fallback: unexpected mode -> safe zero gains */
    kp_use = 0.0;
    kd_use = 0.0;
    ki_use = 0.0;
}

iprev_arr[0] = ra_state.integral_error_rad_s.x;
iprev_arr[1] = ra_state.integral_error_rad_s.y;
iprev_arr[2] = ra_state.integral_error_rad_s.z;

if ((next_mode == RA_FINE || next_mode == RA_HOLD) && ki_use != 0.0) {
    for (i = 0; i < 3; i++) {
        iprop_arr[i] = iprev_arr[i] + e_arr[i] * ra_config.dt_s;
        if (iprop_arr[i] > ra_config.integral_limit_rad_s) {
            iprop_arr[i] = ra_config.integral_limit_rad_s;
        } else if (iprop_arr[i] < -ra_config.integral_limit_rad_s) {
            iprop_arr[i] = -ra_config.integral_limit_rad_s;
        }
    }
} else {
    iprop_arr[0] = iprev_arr[0];
    iprop_arr[1] = iprev_arr[1];
    iprop_arr[2] = iprev_arr[2];
}

lim.min_value = -ra_config.torque_limit_nm;
lim.max_value = ra_config.torque_limit_nm;
lim.max_slew_per_s = 0.0;

for (i = 0; i < 3; i++) {
    t_unlim[i] = -kp_use * e_arr[i] - kd_use * w_arr[i] - ki_use * iprop_arr[i];
}
for (i = 0; i < 3; i++) {
    double limited = 0.0;
    (void)adcs_limit_scalar(t_unlim[i], &lim, &limited);
    t_lim[i] = limited;
}

/* anti-windup: freeze per axis if this update pushes an already-saturated torque farther */
for (i = 0; i < 3; i++) {
    iuse_arr[i] = iprop_arr[i];
}
if ((next_mode == RA_FINE || next_mode == RA_HOLD) && ki_use != 0.0) {
    for (i = 0; i < 3; i++) {
        double old_t, new_t;
        if (t_unlim[i] > ra_config.torque_limit_nm ||
            t_unlim[i] < -ra_config.torque_limit_nm) {
            old_t = -kp_use * e_arr[i] - kd_use * w_arr[i] - ki_use * iprev_arr[i];
            new_t = -kp_use * e_arr[i] - kd_use * w_arr[i] - ki_use * iprop_arr[i];
            if (fabs(new_t) > fabs(old_t) && (new_t * old_t > 0.0) &&
                (old_t > ra_config.torque_limit_nm ||
                 old_t < -ra_config.torque_limit_nm)) {
                iuse_arr[i] = iprev_arr[i];
            }
        }
    }
}
for (i = 0; i < 3; i++) {
    t_unlim[i] = -kp_use * e_arr[i] - kd_use * w_arr[i] - ki_use * iuse_arr[i];
}
sat_mask = 0U;
for (i = 0; i < 3; i++) {
    double limited = 0.0;
    (void)adcs_limit_scalar(t_unlim[i], &lim, &limited);
    t_lim[i] = limited;
    if (t_unlim[i] > ra_config.torque_limit_nm ||
        t_unlim[i] < -ra_config.torque_limit_nm) {
        sat_mask |= (uint32_t)(1U << i);
    }
}

if (next_mode == RA_FINE || next_mode == RA_HOLD) {
    ra_state.integral_error_rad_s = (adcs_vec3_t){iuse_arr[0], iuse_arr[1], iuse_arr[2]};
} else {
    ra_state.integral_error_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
}

torque = (adcs_vec3_t){t_lim[0], t_lim[1], t_lim[2]};

ra_output.mode = next_mode;
ra_output.error_angle_rad = angle;
ra_output.rate_magnitude_rad_s = rate_mag;
ra_output.torque_nm = torque;
ra_output.bad_samples = 0U;
ra_output.saturation_mask = sat_mask;
return;

candidates.raw:
adcs_quat_t q_cur, q_tgt, q_err, q_conj;
adcs_vec3_t e_rot, w_body, torque_cmd, integral_prev, integral_new;
adcs_actuator_limit_t limit;
ra_mode_t next_mode;
double angle = 0.0, rate_mag = 0.0;
unint32 sat_mask = 0U;
int accepted = 1;
double kp_eff, kd_eff, ki_eff;
double vals[3], raw[3];
unint32 axes[3] = {1U, 2U, 4U};
size_t i;

/* 使能/有效标志合法性 */
if ((ra_input.enable != 0 && ra_input.enable != 1) ||
    (ra_input.valid != 0 && ra_input.valid != 1)) {
    accepted = 0;
}
if (ra_input.valid == 0) accepted = 0;

/* disable 优先：清除全部证据、积分、置零力矩 */
if (accepted && ra_input.enable == 0) {
    ra_state.mode = RA_OFF;
    ra_state.transition_samples = 0U;
    ra_state.bad_samples = 0U;
    ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
    ra_output.mode = RA_OFF;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    ra_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    ra_output.saturation_mask = 0U;
    ra_output.bad_samples = 0U;
    return;
}

/* 配置合法性 + 指针 + body rate 有限性 */
if (accepted) {
    int cfg_ok = 1;
    if (!(ra_config.hold_enter_rad >= 0.0)) cfg_ok = 0;
    if (!(ra_config.hold_enter_rad < ra_config.hold_exit_rad)) cfg_ok = 0;
    if (!(ra_config.hold_exit_rad <= ra_config.fine_enter_rad)) cfg_ok = 0;
    if (!(ra_config.fine_enter_rad < ra_config.fine_exit_rad)) cfg_ok = 0;
    if (!(ra_config.fine_exit_rad <= ADCS_PI)) cfg_ok = 0;
    if (!(ra_config.hold_rate_rad_s >= 0.0)) cfg_ok = 0;
    if (!(ra_config.hold_rate_rad_s < ra_config.hold_rate_exit_rad_s)) cfg_ok = 0;
    if (!(ra_config.hold_rate_exit_rad_s <= ra_config.rate_enter_rad_s)) cfg_ok = 0;
    if (!(ra_config.rate_enter_rad_s < ra_config.rate_exit_rad_s)) cfg_ok = 0;
    if (ra_config.rate_samples < 1U || ra_config.rate_samples > 20U) cfg_ok = 0;
    if (ra_config.fine_samples < 1U || ra_config.fine_samples > 20U) cfg_ok = 0;
    if (ra_config.hold_samples < 1U || ra_config.hold_samples > 20U) cfg_ok = 0;
    if (ra_config.max_bad_samples < 1U || ra_config.max_bad_samples > 20U) cfg_ok = 0;
    if (!(isfinite(ra_config.dt_s) && ra_config.dt_s > 0.0)) cfg_ok = 0;
    if (!(isfinite(ra_config.integral_limit_rad_s) && ra_config.integral_limit_rad_s > 0.0)) cfg_ok = 0;
    if (!(isfinite(ra_config.torque_limit_nm) && ra_config.torque_limit_nm > 0.0)) cfg_ok = 0;
    if (!(isfinite(ra_config.kp) && ra_config.kp >= 0.0)) cfg_ok = 0;
    if (!(isfinite(ra_config.kd) && ra_config.kd >= 0.0)) cfg_ok = 0;
    if (!(isfinite(ra_config.ki) && ra_config.ki >= 0.0)) cfg_ok = 0;
    if (ra_input.current_q_bi == NULL || ra_input.target_q_bi == NULL ||
        ra_input.body_rate_rad_s == NULL) cfg_ok = 0;
    if (adcs_quat_normalize(ra_input.current_q_bi, &q_cur) != ADCS_OK) cfg_ok = 0;
    if (adcs_quat_normalize(ra_input.target_q_bi, &q_tgt) != ADCS_OK) cfg_ok = 0;
    if (!adcs_is_finite_vec3(ra_input.body_rate_rad_s)) cfg_ok = 0;
    if (!cfg_ok) accepted = 0;
}

if (!accepted) {
    ra_state.transition_samples = 0U;
    ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
    if (ra_state.bad_samples < ra_config.max_bad_samples) {
        ra_state.bad_samples += 1U;
    }
    if (ra_state.bad_samples >= ra_config.max_bad_samples) {
        ra_state.mode = RA_FAULT;
    } else if (ra_state.mode == RA_FAULT) {
        /* keep latched */
    } else if (ra_state.mode == RA_OFF) {
        /* remains OFF */
    }
    ra_output.mode = ra_state.mode;
    ra_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    ra_output.saturation_mask = 0U;
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.error_angle_rad = 0.0;
    ra_output.rate_magnitude_rad_s = 0.0;
    return;
}

/* 误差：target*conjugate(current)，选最短符号 */
q_conj = adcs_quat_conjugate(&q_cur);
q_err = adcs_quat_multiply(&q_tgt, &q_conj);
if (q_err.w < 0.0) {
    q_err.w = -q_err.w;
    q_err.x = -q_err.x;
    q_err.y = -q_err.y;
    q_err.z = -q_err.z;
}
{
    double s = sqrt(q_err.x * q_err.x + q_err.y * q_err.y + q_err.z * q_err.z);
    if (s < ADCS_EPS_QUAT) {
        e_rot = (adcs_vec3_t){2.0 * q_err.x, 2.0 * q_err.y, 2.0 * q_err.z};
    } else {
        double ang = 2.0 * atan2(s, q_err.w);
        e_rot = adcs_vec3_scale(&(adcs_vec3_t){q_err.x, q_err.y, q_err.z}, ang / s);
    }
}
w_body = *ra_input.body_rate_rad_s;
angle = adcs_vec3_norm(&e_rot);
rate_mag = adcs_vec3_norm(&w_body);

/* 模式迁移 */
next_mode = ra_state.mode;

if (ra_state.mode == RA_OFF) {
    if (rate_mag > ra_config.rate_enter_rad_s) {
        next_mode = RA_RATE_DAMP;
    } else {
        next_mode = RA_COARSE;
    }
    ra_state.transition_samples = 0U;
} else if (ra_state.mode == RA_RATE_DAMP) {
    if (rate_mag >= ra_config.rate_exit_rad_s) {
        ra_state.transition_samples = 0U;
    } else if (rate_mag <= ra_config.rate_enter_rad_s) {
        if (ra_state.transition_samples < ra_config.rate_samples) {
            ra_state.transition_samples += 1U;
        }
        if (ra_state.transition_samples >= ra_config.rate_samples) {
            next_mode = RA_COARSE;
            ra_state.transition_samples = 0U;
        }
    } else {
        ra_state.transition_samples = 0U;
    }
} else if (ra_state.mode == RA_COARSE) {
    if (angle <= ra_config.fine_enter_rad && rate_mag <= ra_config.rate_enter_rad_s) {
        if (ra_state.transition_samples < ra_config.fine_samples) {
            ra_state.transition_samples += 1U;
        }
        if (ra_state.transition_samples >= ra_config.fine_samples) {
            next_mode = RA_FINE;
            ra_state.transition_samples = 0U;
        }
    } else {
        ra_state.transition_samples = 0U;
    }
} else if (ra_state.mode == RA_FINE) {
    if (angle >= ra_config.fine_exit_rad || rate_mag >= ra_config.rate_exit_rad_s) {
        next_mode = RA_COARSE;
        ra_state.transition_samples = 0U;
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
    } else if (angle <= ra_config.hold_enter_rad &&
               rate_mag <= ra_config.hold_rate_rad_s) {
        if (ra_state.transition_samples < ra_config.hold_samples) {
            ra_state.transition_samples += 1U;
        }
        if (ra_state.transition_samples >= ra_config.hold_samples) {
            next_mode = RA_HOLD;
            ra_state.transition_samples = 0U;
        }
    } else {
        ra_state.transition_samples = 0U;
    }
} else if (ra_state.mode == RA_HOLD) {
    if (angle >= ra_config.hold_exit_rad ||
        rate_mag >= ra_config.hold_rate_exit_rad_s) {
        next_mode = RA_FINE;
        ra_state.transition_samples = 0U;
    } else {
        ra_state.transition_samples = 0U;
    }
} else if (ra_state.mode == RA_FAULT) {
    next_mode = RA_FAULT;
}

ra_state.mode = next_mode;

/* 控制律增益按当前模式 */
kp_eff = ra_config.kp;
kd_eff = ra_config.kd;
ki_eff = ra_config.ki;

if (next_mode == RA_RATE_DAMP) {
    kp_eff = 0.0;
    ki_eff = 0.0;
} else if (next_mode == RA_COARSE) {
